CREATE TABLE IF NOT EXISTS public."worldLocation" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" text NOT NULL,
  "type" text NOT NULL,
  "parentId" integer,
  "description" text,
  "publicationStatus" text NOT NULL DEFAULT 'DRAFT',
  "operationalStatus" text NOT NULL DEFAULT 'ACTIVE',
  "claimability" text NOT NULL DEFAULT 'NOT_CLAIMABLE',
  "createdAt" timestamptz NOT NULL DEFAULT now(),
  "updatedAt" timestamptz NOT NULL,
  CONSTRAINT "worldLocation_parentId_fkey"
    FOREIGN KEY ("parentId") REFERENCES public."worldLocation"("id")
    ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT "worldLocation_type_check"
    CHECK ("type" IN ('CONTINENT', 'REGION', 'CITY', 'ISLAND', 'ARCHIPELAGO', 'FLOATING_ISLAND', 'NEIGHBORHOOD', 'BUILDING', 'POINT_OF_INTEREST')),
  CONSTRAINT "worldLocation_publicationStatus_check"
    CHECK ("publicationStatus" IN ('DRAFT', 'PUBLISHED', 'ARCHIVED')),
  CONSTRAINT "worldLocation_operationalStatus_check"
    CHECK ("operationalStatus" IN ('ACTIVE', 'INACTIVE')),
  CONSTRAINT "worldLocation_claimability_check"
    CHECK ("claimability" IN ('NOT_CLAIMABLE', 'CLAIMABLE'))
);

CREATE INDEX IF NOT EXISTS "worldLocation_parentId_idx" ON public."worldLocation"("parentId");
CREATE INDEX IF NOT EXISTS "worldLocation_type_idx" ON public."worldLocation"("type");
CREATE INDEX IF NOT EXISTS "worldLocation_publicationStatus_idx" ON public."worldLocation"("publicationStatus");

ALTER TABLE public."worldLocation" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "worldLocation_published_read" ON public."worldLocation";
CREATE POLICY "worldLocation_published_read"
  ON public."worldLocation"
  FOR SELECT TO anon, authenticated
  USING ("publicationStatus" = 'PUBLISHED');
GRANT SELECT ON public."worldLocation" TO anon, authenticated;
